import { test } from 'node:test';
import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { criarContador, escutarUmaVez } from './solution.mjs';

test('criarContador conta todas as emissões', () => {
  const emissor = new EventEmitter();
  const contar = criarContador(emissor, 'clique');
  emissor.emit('clique');
  emissor.emit('clique');
  assert.equal(contar(), 2);
});

test('escutarUmaVez conta só a primeira emissão', () => {
  const emissor = new EventEmitter();
  const contar = escutarUmaVez(emissor, 'clique');
  emissor.emit('clique');
  emissor.emit('clique');
  emissor.emit('clique');
  assert.equal(contar(), 1);
});

test('também funciona com um emissor simulado (injeção)', () => {
  const ouvintes = [];
  const emissorFalso = {
    on(evento, fn) { ouvintes.push([evento, fn]); },
    emit(evento) {
      for (const [e, fn] of ouvintes) {
        if (e === evento) fn();
      }
    },
  };
  const contar = criarContador(emissorFalso, 'ping');
  emissorFalso.emit('ping');
  emissorFalso.emit('ping');
  assert.equal(contar(), 2);
});

test('lança erro se o emissor não tiver on', () => {
  assert.throws(() => criarContador({}, 'clique'), /emissor/);
});

