export function criarContador(emissor, evento) {
  if (!emissor || typeof emissor.on !== 'function') {
    throw new Error('emissor precisa ter um método on');
  }

  let total = 0;
  emissor.on(evento, () => {
    total += 1;
  });

  return () => total;
}

export function escutarUmaVez(emissor, evento) {
  if (!emissor || typeof emissor.once !== 'function') {
    throw new Error('emissor precisa ter um método once');
  }

  let total = 0;
  emissor.once(evento, () => {
    total += 1;
  });

  return () => total;
}
